#!/bin/sh
docker exec -i "${PERF_PG:-perf-a0-pg}" psql -U postgres -d "${PERF_DB:-perf}" -c "select row_number() over (order by total_exec_time desc) as n, queryid, calls, round(total_exec_time::numeric,1) as total_ms, round(mean_exec_time::numeric,2) as mean_ms, rows, left(regexp_replace(query, '\s+', ' ', 'g'), ${PERF_QLEN:-140}) as query from pg_stat_statements where dbid = (select oid from pg_database where datname = '${PERF_DB:-perf}') and query not ilike '%pg_stat_statements%' order by total_exec_time desc limit 20"
